import dev.jdgomez.customnotifier.build.AppVersion

plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.kotlin.compose)
    alias(libs.plugins.roborazzi)
    alias(libs.plugins.ksp)
    alias(libs.plugins.room)
}

kotlin {
    jvmToolchain(21)
    compilerOptions {
        allWarningsAsErrors = true
    }
}

room3 {
    schemaDirectory("$projectDir/schemas")
}

// The version is generated by release-please into version.txt; the version code is derived from it.
val appVersion = AppVersion.parse(rootProject.file("version.txt").readText())

// The upload key comes only from the environment (set by the release workflow); never from the repository.
val signingVariables =
    listOf(
        "CN_UPLOAD_KEYSTORE",
        "CN_UPLOAD_KEYSTORE_PASSWORD",
        "CN_UPLOAD_KEY_ALIAS",
        "CN_UPLOAD_KEY_PASSWORD",
    ).associateWith { providers.environmentVariable(it).orNull?.takeIf(String::isNotEmpty) }
val missingSigningVariables = signingVariables.filterValues { it == null }.keys
check(missingSigningVariables.isEmpty() || missingSigningVariables.size == signingVariables.size) {
    "Release signing is half configured; missing environment variables: ${missingSigningVariables.joinToString()}."
}

android {
    namespace = "dev.jdgomez.customnotifier"
    compileSdk = 37

    defaultConfig {
        applicationId = "dev.jdgomez.customnotifier"
        minSdk = 26
        targetSdk = 37
        versionCode = appVersion.code
        versionName = appVersion.name
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        // Each instrumented test starts from a clean app state.
        testInstrumentationRunnerArguments["clearPackageData"] = "true"
    }

    signingConfigs {
        if (missingSigningVariables.isEmpty()) {
            create("upload") {
                storeFile = file(signingVariables.getValue("CN_UPLOAD_KEYSTORE")!!)
                storePassword = signingVariables.getValue("CN_UPLOAD_KEYSTORE_PASSWORD")
                keyAlias = signingVariables.getValue("CN_UPLOAD_KEY_ALIAS")
                keyPassword = signingVariables.getValue("CN_UPLOAD_KEY_PASSWORD")
            }
        }
    }

    buildTypes {
        // Shrunk like the build the user installs. Signed with the upload key only when the release workflow
        // provides it through the environment (ADR 0014, 0018); otherwise unsigned.
        release {
            signingConfig = signingConfigs.findByName("upload")
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
        }
    }

    buildFeatures {
        compose = true
    }

    testOptions {
        execution = "ANDROIDX_TEST_ORCHESTRATOR"
        unitTests {
            isIncludeAndroidResources = true
        }
    }

    // Calendar event texts are built in a language other than the device's, so every language must stay in the base module.
    bundle {
        language {
            enableSplit = false
        }
    }

    sourceSets {
        // buildSrc is not part of `./gradlew test`: compile the version rules into the app's unit tests so they run there.
        getByName("test").kotlin.directories.add("../buildSrc/src/main/kotlin")
    }

    lint {
        warningsAsErrors = true
        abortOnError = true
        checkDependencies = true
    }
}

// Screenshot tests read the committed references at run time; declaring them as an input
// makes a changed reference re-run verification instead of reusing an up-to-date or cached pass.
tasks.withType<Test>().configureEach {
    inputs
        .dir("src/test/screenshots")
        .withPropertyName("screenshotReferences")
        .withPathSensitivity(PathSensitivity.RELATIVE)
    // Robolectric's FileDescriptor shadow reaches into a JDK-internal package that JDK 17+ encapsulates.
    jvmArgs("--add-exports=java.base/jdk.internal.access=ALL-UNNAMED")
}

